-- criar_pedido passa a aplicar o desconto trocado com pontos (pontos_resgates
-- "disponivel"): percentual sobre o subtotal já com cupom; o pedido guarda o
-- valor em desconto_pontos e soma em desconto. Mesma assinatura e retorno.
create or replace function public.criar_pedido(p_endereco_id uuid, p_observacoes text default null, p_cupom text default null)
returns table(pedido_id uuid, numero bigint, total numeric) language plpgsql security definer set search_path to 'public' as $function$ declare v_uid uuid := auth.uid(); v_perfil public.perfis%rowtype; v_end public.enderecos%rowtype; v_subtotal numeric(12,2); v_desconto numeric(12,2) := 0; v_cupom text; v_pedido public.pedidos%rowtype; v_qtd_itens integer; v_resgate uuid; v_desc_pontos numeric(12,2) := 0; begin select * into v_perfil from public.perfis where id = v_uid; if not found or not (v_perfil.cadastro_aprovado or v_perfil.tipo = 'admin') then raise exception 'Cadastro ainda nao aprovado' using errcode = '42501'; end if; select * into v_end from public.enderecos where id = p_endereco_id and usuario_id = v_uid; if not found then raise exception 'Informe o endereco de entrega' using errcode = 'P0001'; end if; perform 1 from public.carrinho_itens where usuario_id = v_uid for update; select count(*), coalesce(sum(ci.quantidade * p.preco_efetivo), 0) into v_qtd_itens, v_subtotal from public.carrinho_itens ci join public.produtos p on p.id = ci.produto_id and p.ativo where ci.usuario_id = v_uid; if v_qtd_itens = 0 then raise exception 'Seu carrinho esta vazio' using errcode = 'P0001'; end if; if nullif(trim(p_cupom), '') is not null then select c.codigo, least(c.valor, v_subtotal) into v_cupom, v_desconto from public.cupons c where upper(c.codigo) = upper(trim(p_cupom)) and c.ativo; if v_cupom is null then raise exception 'Cupom invalido' using errcode = 'P0001'; end if; end if; select d.resgate_id, d.valor into v_resgate, v_desc_pontos from public.pedido_desconto_pontos(v_uid, v_subtotal - v_desconto) d; v_desc_pontos := coalesce(v_desc_pontos, 0); insert into public.pedidos (cliente_id, subtotal, desconto, total, cupom_codigo, observacoes, endereco_entrega, cliente_snapshot, desconto_pontos, pontos_resgate_id) values (v_uid, v_subtotal, v_desconto + v_desc_pontos, v_subtotal - v_desconto - v_desc_pontos, v_cupom, nullif(trim(p_observacoes), ''), jsonb_build_object('cep', v_end.cep, 'rua', v_end.rua, 'numero', v_end.numero, 'complemento', v_end.complemento, 'bairro', v_end.bairro, 'cidade', v_end.cidade, 'estado', v_end.estado), jsonb_build_object('nome', v_perfil.nome, 'razao_social', v_perfil.razao_social, 'cnpj', v_perfil.cnpj, 'telefone', v_perfil.telefone, 'codigo', v_perfil.codigo), v_desc_pontos, v_resgate) returning * into v_pedido; if v_resgate is not null then perform public.pedido_usar_resgate(v_resgate, v_pedido.id); end if; perform public.pedido_copiar_itens(v_pedido.id, v_uid); perform public.pedido_atualizar_vendas(v_uid); perform public.pedido_limpar_carrinho(v_uid); perform public.pedido_resetar_avisos_carrinho(v_uid); return query select v_pedido.id, v_pedido.numero, v_pedido.total; end $function$;
